<!-- This file is generated by AI. -->
<!--
  开始界面: 最近项目 + 新建 / 打开。
-->
<script lang="ts">
  import { open } from '@tauri-apps/plugin-dialog';
  import { revealItemInDir } from '@tauri-apps/plugin-opener';
  import { onMount } from 'svelte';

  import { moveToTrash } from '../commands/server';
  import { requestAlert, requestConfirm } from '../confirm';
  import { gameConfigSummary } from '../lib/gameConfig';
  import { fs } from '../lib/fs';
  import {
    filterRecentProjects,
    projectDisplayName,
    removeRecentProject,
    sortRecentProjects,
  } from '../lib/recentProjects';
  import { openProject, readProjectConfig } from '../project';
  import { actions, appStore } from '../state/store.svelte';
  import Button from './Button.svelte';
  import ContextMenu, { type ContextMenuItem } from './ContextMenu.svelte';
  import Input from './Input.svelte';
  import NewProjectDialog from './NewProjectDialog.svelte';
  import RecentProjectCard, { type RecentProjectView } from './RecentProjectCard.svelte';

  /** 每个项目的探测结果 (目录是否还在、config 里的名字/简介/封面)。 */
  interface ProjectState {
    available: boolean;
    name?: string;
    description?: string;
    titleImg?: string;
  }

  let query = $state('');
  let creating = $state(false);
  let states = $state<Record<string, ProjectState>>({});
  let menu = $state<{ path: string; x: number; y: number } | null>(null);

  /*
   * 只在挂载时记下要刷新的项目路径。
   *
   * 刷新过程本身会写回 settings; 若把 settings 作为依赖, 就会"刷新 -> 设置变化 -> 再刷新"
   * 地循环下去。因此这里取一次快照。
   */
  let initialPaths: string[] = [];

  const recents = $derived(sortRecentProjects(appStore.settings.recentProjects));

  const views = $derived<RecentProjectView[]>(
    recents.map((item) => {
      const state = states[item.path.toLowerCase()];
      return {
        path: item.path,
        name: state?.name ?? projectDisplayName(item),
        titleImg: state?.titleImg ?? item.titleImg,
        lastOpened: item.lastOpened,
        available: state?.available ?? true,
      };
    })
  );

  const visible = $derived(filterRecentProjects(views, query));

  onMount(() => {
    initialPaths = appStore.settings.recentProjects.map((item) => item.path);
    void refreshStates(initialPaths);
  });

  /** 探一遍这些项目目录: 还在不在、config 里写了什么。 */
  async function refreshStates(paths: string[]): Promise<void> {
    if (paths.length === 0) return;

    const results = await Promise.all(
      paths.map(async (path) => {
        const [config, stat] = await Promise.all([readProjectConfig(path), fs.exists(path)]);
        return { path, config, available: stat.exists };
      })
    );

    const next: Record<string, ProjectState> = {};
    for (const result of results) {
      const summary = result.config ? gameConfigSummary(result.config.entries) : null;
      next[result.path.toLowerCase()] = {
        available: result.available,
        name: summary?.name || undefined,
        description: summary?.description || undefined,
        titleImg: summary?.titleImg || undefined,
      };
    }
    states = next;

    // 顺手把最新值写回设置: 下次启动先按缓存显示, 再异步刷新
    actions.updateSettings({
      recentProjects: appStore.settings.recentProjects.map((item) => {
        const state = next[item.path.toLowerCase()];
        if (!state) return item;
        return {
          ...item,
          name: state.name ?? item.name,
          description: state.description ?? item.description,
          titleImg: state.titleImg ?? item.titleImg,
        };
      }),
    });
  }

  /**
   * 打开项目。
   *
   * 过程里**不动页面**: 不显示"正在打开"、不在页面上写错误 —— 打开是用户自己的动作,
   * 成功就是页面切到编辑器, 失败就弹一个框说清楚。
   */
  async function openPath(path: string): Promise<void> {
    try {
      await openProject(path);
    } catch (error) {
      requestAlert('无法打开项目', `${path}\n\n${String(error)}`);
    }
  }

  async function pickAndOpen(): Promise<void> {
    const dir = await open({ directory: true, title: '选择 WebGAL 项目目录' });
    if (typeof dir === 'string') await openPath(dir);
  }

  function removeFromList(path: string): void {
    actions.updateSettings({ recentProjects: removeRecentProject(appStore.settings.recentProjects, path) });
  }

  /** 移入回收站是不可逆到"要点两次"的操作, 因此仍走确认框 (与"从列表移除"分开)。 */
  function trashProject(path: string, name: string): void {
    requestConfirm({
      title: '移入回收站',
      description: `将「${name}」的整个项目文件夹移入系统回收站（可恢复）。`,
      confirmLabel: '移入回收站',
      danger: true,
      action: () => {
        void (async () => {
          try {
            await moveToTrash(path);
            removeFromList(path);
          } catch (error) {
            requestAlert('删除失败', String(error));
          }
        })();
      },
    });
  }

  const menuProject = $derived(menu ? views.find((item) => item.path === menu?.path) : undefined);

  const menuItems = $derived<ContextMenuItem[]>(
    menuProject
      ? [
          /*
           * 这里**没有**「打开项目」: 卡片本身就是打开入口 (左键单击即打开), 菜单里再放一条
           * 同名项既重复、又容易让人以为卡片点击没生效。
           */
          {
            key: 'reveal',
            label: '在文件管理器中打开',
            iconName: 'OpenFolder',
            onClick: () => void revealItemInDir(menuProject.path),
          },
          { key: 'sep-1', separator: true },
          {
            key: 'remove',
            label: '从列表移除',
            iconName: 'Dismiss',
            onClick: () => removeFromList(menuProject.path),
          },
          {
            key: 'trash',
            label: '移入回收站',
            iconName: 'Delete',
            danger: true,
            onClick: () => trashProject(menuProject.path, menuProject.name),
          },
        ]
      : []
  );
</script>

<div class="welcome">
  <header class="welcome-head">
    <div class="welcome-brand">
      <img class="welcome-mark" src="icon.svg" alt="" draggable="false" />
      <div class="welcome-brand-text">
        <h1 class="welcome-title">WebGAL Ink</h1>
        <p class="welcome-subtitle">WebGAL 视觉小说代码编辑器</p>
      </div>
    </div>

    <div class="welcome-toolbar">
      <div class="welcome-search">
        <!-- 放大镜落在输入框边框以内 -->
        <Input placeholder="搜索项目" bind:value={query} icon="Search" />
      </div>
      <Button appearance="primary" icon="Add" onclick={() => (creating = true)}>新建项目</Button>
      <Button icon="FolderOpen" onclick={() => void pickAndOpen()}>打开项目</Button>
    </div>
  </header>

  <div class="welcome-body">
    <div class="welcome-section-head">
      <h3>最近项目</h3>
      {#if views.length > 0}
        <span class="muted">
          {query.trim() ? `${visible.length} / ${views.length}` : `${views.length} 个`}
        </span>
      {/if}
    </div>

    {#if views.length === 0}
      <p class="welcome-empty">还没有项目。用「新建项目」由引擎生成一个，或「打开项目」打开已有的 WebGAL 项目目录。</p>
    {:else if visible.length === 0}
      <p class="welcome-empty">没有匹配「{query.trim()}」的项目</p>
    {:else}
      <div class="project-grid">
        {#each visible as project (project.path)}
          <RecentProjectCard
            {project}
            onOpen={() => void openPath(project.path)}
            onMenu={(position) => (menu = { path: project.path, x: position.x, y: position.y })}
            onCardContextMenu={(event) => {
              event.preventDefault();
              menu = { path: project.path, x: event.clientX, y: event.clientY };
            }}
          />
        {/each}
      </div>
    {/if}
  </div>

  {#if menu && menuProject}
    <ContextMenu x={menu.x} y={menu.y} items={menuItems} onClose={() => (menu = null)} />
  {/if}

  {#if creating}
    <NewProjectDialog
      onClose={() => (creating = false)}
      onOpenEngineSettings={() => {
        creating = false;
        actions.setSettingsCategory('engine');
        actions.setSettingsOpen(true);
      }}
    />
  {/if}
</div>
